content.text:
{
  "name": "电动位移台执行器",
  "name_en": "Motorized Stage Actuator",
  "manufacturer": "",
  "description": "一种用于线性或旋转定位的电动执行器/位移台，可进行初始化、回零、绝对与相对移动、位置读取和停止运动，常用于光学对准、样品定位及实验自动化扫描。",
  "description_en": "A motorized actuator or positioning stage used for linear or rotational positioning. It supports initialization, homing, absolute and relative moves, position readback, and motion stop, and is commonly used for optical alignment, sample positioning, and automated laboratory scanning.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭并释放位移台硬件连接。",
      "description_en": "Close and release the stage hardware connection."
    },
    {
      "action_name": "auto-check_position",
      "description": "获取当前位置。",
      "description_en": "Get the current position."
    },
    {
      "action_name": "auto-ini_stage",
      "description": "初始化位移台并建立通信。",
      "description_en": "Initialize the motorized stage and establish communication."
    },
    {
      "action_name": "auto-move_abs",
      "description": "移动到指定绝对位置。",
      "description_en": "Move to a specified absolute position."
    },
    {
      "action_name": "auto-move_rel",
      "description": "按给定位移量相对移动。",
      "description_en": "Move by a specified relative offset."
    },
    {
      "action_name": "auto-Move_Stoped",
      "description": "报告运动已停止及当前位置。",
      "description_en": "Report that motion has stopped and provide the current position."
    },
    {
      "action_name": "auto-move_home",
      "description": "移动到回零或初始位置。",
      "description_en": "Move to the home or initial position."
    },
    {
      "action_name": "auto-move_done",
      "description": "报告运动完成及当前位置。",
      "description_en": "Report that motion is complete and provide the current position."
    },
    {
      "action_name": "auto-queue_command",
      "description": "执行排队的控制命令。",
      "description_en": "Execute a queued control command."
    },
    {
      "action_name": "auto-stop_motion",
      "description": "停止当前运动。",
      "description_en": "Stop the current motion."
    },
    {
      "action_name": "auto-update_settings",
      "description": "更新运动相关设置参数。",
      "description_en": "Update motion-related settings."
    }
  ],
  "tag_hints": [
    "motorized stage",
    "actuator positioning",
    "absolute and relative motion",
    "sample positioning",
    "optical alignment",
    "home return",
    "motion control"
  ]
}

